<script lang="ts">
	import { AlertTriangle, ArrowLeft, BatteryCharging, Download, Printer, RefreshCw } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import BmsCellChart from './BmsCellChart.svelte';
	import BmsCellDataPanel from './BmsCellDataPanel.svelte';
	import { exportBmsStringRangeUrl, getBmsStringReadiness, getBmsStringTelemetry, hasBmsSession, listBmsStrings, type BatteryString, type BmsStringTelemetry, type StringReadinessTrace } from '$lib/services/bms-api';

	let { stringIndex, onBack }: { stringIndex:number; onBack:()=>void }=$props();
	let config=$state<BatteryString|null>(null),telemetry=$state<BmsStringTelemetry|null>(null),readiness=$state<StringReadinessTrace|null>(null);
	let tab=$state<'voltage'|'temperature'|'soc'>('voltage'),loading=$state(false),error=$state(''),rangeStart=$state(''),rangeEnd=$state('');
	let title=$derived(config?.stringName??telemetry?.stringName??`String ${stringIndex}`),cells=$derived(telemetry?.cells??[]);
	let summary=$derived(telemetry?.summary);

	onMount(()=>{const end=new Date(),start=new Date(end.getTime()-86400000);rangeStart=localInput(start);rangeEnd=localInput(end);void load();const dataTimer=setInterval(()=>void loadTelemetry(false),15000);const readyTimer=setInterval(()=>{if(!readiness?.complete)void loadReadiness()},2000);return()=>{clearInterval(dataTimer);clearInterval(readyTimer)}});
	async function load(){loading=true;error='';try{if(!hasBmsSession())throw new Error('Authenticate with the BMS platform to read live string data.');const [configs]=await Promise.all([listBmsStrings(),loadTelemetry(false),loadReadiness()]);config=configs.find(item=>item.stringIndex===stringIndex)??null;if(!config)throw new Error('Battery string not found.')}catch(cause){error=cause instanceof Error?cause.message:'Unable to load battery string data.'}finally{loading=false}}
	async function loadTelemetry(activity=true){if(activity)loading=true;try{telemetry=await getBmsStringTelemetry(stringIndex);if(activity)error=''}catch(cause){error=cause instanceof Error?cause.message:'Unable to refresh live string data.'}finally{if(activity)loading=false}}
	async function loadReadiness(){try{readiness=await getBmsStringReadiness(stringIndex)}catch{/* Diagnostic data is optional while the string is starting. */}}
	function localInput(value:Date){const offset=value.getTimezoneOffset()*60000;return new Date(value.getTime()-offset).toISOString().slice(0,16)}
	function value(input:number|null|undefined,digits=2){return input===null||input===undefined?'N/A':input.toFixed(digits)}
	function elapsed(timestamp:number|null){return !readiness||timestamp===null?'pending':`${((timestamp-readiness.startedAt)/1000).toFixed(1)} s`}
	function exportRange(){const a=document.createElement('a');a.href=exportBmsStringRangeUrl(String(stringIndex),rangeStart,rangeEnd);a.download='';a.click()}
</script>

<section class="page">
	<div class="head"><div><button class="back" onclick={onBack}><ArrowLeft size={18}/>Back to dashboard</button><div class="title"><span><BatteryCharging size={21}/></span><div><h2>{title}</h2><p>Live battery string measurements and cell diagnostics.</p></div></div></div><div class="head-actions"><button class:loading class="refresh" disabled={loading} aria-label="Refresh string data" onclick={()=>loadTelemetry()}><RefreshCw size={17}/></button><button class="secondary" onclick={()=>window.print()}><Printer size={16}/>Print</button><button class="primary" onclick={exportRange}><Download size={16}/>Export CSV</button></div></div>
	{#if error}<div class="alert error"><AlertTriangle size={17}/>{error}</div>{/if}
	{#if readiness}<div class:complete={readiness.complete} class="readiness"><div><strong>{readiness.complete?'Readiness complete':'String readiness in progress'}</strong><span>{readiness.operation} · TA {readiness.successfulTaIds.length}/{readiness.expectedCellCount} · TC {readiness.tcState}</span></div><div><span>ConfigAdmin {elapsed(readiness.configAdminCompletedAt)}</span><span>First TA/TC {elapsed(readiness.firstTaReadAt)} / {elapsed(readiness.firstTcReadAt)}</span><span>Snapshot {elapsed(readiness.calculatorSnapshotAt)}</span></div>{#if readiness.pendingTaIds.length||readiness.failedTaIds.length}<small>{readiness.pendingTaIds.length?`Pending TA: ${readiness.pendingTaIds.join(', ')}. `:''}{readiness.failedTaIds.length?`Failed TA: ${readiness.failedTaIds.join(', ')}.`:''}</small>{/if}</div>{/if}
	{#if telemetry?.calculation.snapshotStale}<div class="alert error">Live snapshot is stale{telemetry.calculation.snapshotAgeMs!==null?` (${Math.floor(telemetry.calculation.snapshotAgeMs/1000)} seconds old)`:''}. Values remain N/A until a fresh snapshot is published.</div>{:else if telemetry?.calculation.error}<div class="alert error">SoC/SoH calculation failed: {telemetry.calculation.error}</div>{:else if telemetry&&!telemetry.calculation.calculatorAvailable}<div class="alert warning">SoC/SoH calculator is not active yet.</div>{:else if telemetry&&telemetry.calculation.calculatedSocCellCount===0&&telemetry.calculation.calculatedSohCellCount===0}<div class="alert warning">No cells currently have usable SoC or SoH calculation inputs.</div>{/if}
	{#if telemetry?.statusMessage}<div class="alert warning">{telemetry.statusMessage}</div>{/if}
	{#if telemetry?.calculation.unavailableTaCellIds.length}<div class="alert warning">TA communication unavailable for cells: {telemetry.calculation.unavailableTaCellIds.join(', ')}.</div>{/if}{#if telemetry?.calculation.stringWarning}<div class="alert warning">String TC communication warning: {telemetry.calculation.stringWarning}</div>{/if}

	<section class="identity card"><div><span>String</span><strong>{title}</strong></div><div><span>Cell quantity</span><strong>{config?.cellQty??telemetry?.cellQty??'—'}</strong></div><div><span>Cell brand</span><strong>{config?.cellBrand||'—'}</strong></div><div><span>Cell model</span><strong>{config?.cellModel||'—'}</strong></div><div class="range"><label>From<input type="datetime-local" bind:value={rangeStart}/></label><label>To<input type="datetime-local" bind:value={rangeEnd}/></label></div></section>

	<section class="card summary-card"><header><h3>String Data</h3><span>Snapshot {telemetry?.calculation.snapshotTimestamp?new Date(telemetry.calculation.snapshotTimestamp).toLocaleString():'N/A'}</span></header><div class="metrics"><article><span>String Vol (V)</span><strong>{value(summary?.stringVoltage,3)}</strong></article><article><span>Current (A)</span><strong>{value(summary?.stringCurrent,3)}</strong></article><article><span>Ambient (°C)</span><strong>{value(summary?.ambientTemperature,1)}</strong></article><article><span>String SoC (%)</span><strong>{value(summary?.stringSoC,3)}</strong></article><article><span>String SoH (%)</span><strong>{value(summary?.stringSoH,3)}</strong></article><article><span>Avg Vol (V)</span><strong>{value(summary?.avgVoltage,3)}</strong></article><article><span>Avg Temp (°C)</span><strong>{value(summary?.avgTemperature,1)}</strong></article><article><span>Avg Rst (µΩ)</span><strong>{value(summary?.avgResistance,1)}</strong></article><article><span>Max Vol</span><strong>#{summary?.maxVoltageCellIndex??'—'} · {value(summary?.maxVoltage,3)}</strong></article><article><span>Min Vol</span><strong>#{summary?.minVoltageCellIndex??'—'} · {value(summary?.minVoltage,3)}</strong></article><article><span>Max Temp</span><strong>#{summary?.maxTemperatureCellIndex??'—'} · {value(summary?.maxTemperature,1)}</strong></article><article><span>Min Temp</span><strong>#{summary?.minTemperatureCellIndex??'—'} · {value(summary?.minTemperature,1)}</strong></article><article><span>Max Rst</span><strong>#{summary?.maxResistanceCellIndex??'—'} · {value(summary?.maxResistance,1)}</strong></article><article><span>Min Rst</span><strong>#{summary?.minResistanceCellIndex??'—'} · {value(summary?.minResistance,1)}</strong></article></div></section>

	<div class="tabs"><button class:active={tab==='voltage'} onclick={()=>tab='voltage'}>Voltage / Resistance</button><button class:active={tab==='temperature'} onclick={()=>tab='temperature'}>Temperature / IR</button><button class:active={tab==='soc'} onclick={()=>tab='soc'}>SoC / SoH</button></div>
	<div class="data-sections"><BmsCellDataPanel mode={tab} {cells} {config} expectedCount={config?.cellQty??telemetry?.cellQty??0}/><BmsCellChart mode={tab} {cells}/></div>
</section>

<style>
	.page{animation:enter .18s ease-out}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:15px}.back{display:flex;align-items:center;gap:7px;margin:0 0 13px;padding:0;border:0;color:#41618f;background:transparent;font:inherit;cursor:pointer}.title{display:flex;align-items:center;gap:10px}.title>span{display:grid;width:38px;height:38px;place-items:center;border-radius:10px;color:#2653ba;background:#eaf0ff}.title h2{margin:0;color:#172b4d;font-size:24px;font-weight:500}.title p{margin:5px 0 0;color:#718096;font-size:16px}.head-actions{display:flex;gap:8px}.primary,.secondary,.refresh{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border-radius:8px;font:inherit;cursor:pointer}.primary{border:0;color:#fff;background:#1749ad}.secondary,.refresh{border:1px solid #d8e0eb;color:#40516f;background:#fff}.refresh{width:38px;padding:0}.refresh.loading :global(svg){animation:spin .8s linear infinite}.alert{display:flex;align-items:center;gap:8px;margin-bottom:11px;padding:10px 12px;border-radius:8px;font-size:14px}.alert.error{border:1px solid #f1cecb;color:#b42318;background:#fff2f1}.alert.warning{border:1px solid #eddfbc;color:#7d5a23;background:#fff9ea}.readiness{display:grid;grid-template-columns:1fr auto;gap:6px 16px;margin-bottom:11px;padding:11px 13px;border:1px solid #ecdcae;border-radius:8px;color:#765925;background:#fff9e9}.readiness.complete{border-color:#c9e6d4;color:#28734b;background:#f1faf4}.readiness strong,.readiness span{display:block}.readiness strong{font-weight:500}.readiness div>span{margin-top:3px;font-size:13px}.readiness div:nth-child(2){display:flex;align-items:center;gap:11px}.readiness small{grid-column:1/-1}.card{border:1px solid #e1e7f0;border-radius:11px;background:#fff}.identity{display:flex;align-items:center;gap:32px;padding:15px 17px}.identity>div>span,.identity>div>strong{display:block}.identity>div>span{color:#8792a4;font-size:13px}.identity>div>strong{margin-top:4px;color:#31415c;font-weight:500}.identity .range{display:flex;gap:9px;margin-left:auto}.identity label{display:grid;gap:4px;color:#718096;font-size:13px}.identity input{height:36px;padding:0 8px;border:1px solid #d7dfeb;border-radius:7px;color:#35445e;font:inherit}.summary-card{margin-top:13px;overflow:hidden}.card>header{display:flex;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid #edf0f4}.card>header h3{margin:0;color:#31415c;font-size:16px;font-weight:500}.card>header>span{color:#8792a4;font-size:13px}.metrics{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:1px;background:#edf1f6}.metrics article{min-height:73px;padding:12px;background:#fff}.metrics span,.metrics strong{display:block}.metrics span{color:#8792a4;font-size:13px}.metrics strong{margin-top:7px;color:#30415c;font-size:15px;font-weight:500}.tabs{display:flex;gap:4px;margin-top:14px;border-bottom:1px solid #e1e7f0}.tabs button{height:40px;padding:0 14px;border:0;border-bottom:2px solid transparent;color:#65738b;background:transparent;font:inherit;cursor:pointer}.tabs button.active{border-color:#2454b6;color:#1749ad}.data-sections{display:grid;gap:14px;margin-top:13px}@keyframes spin{to{transform:rotate(360deg)}}@keyframes enter{from{opacity:0;transform:translateY(4px)}}@media(max-width:1100px){.metrics{grid-template-columns:repeat(4,1fr)}.identity{flex-wrap:wrap}.identity .range{width:100%;margin-left:0}}@media(max-width:700px){.head{align-items:stretch;flex-direction:column}.head-actions{justify-content:flex-end}.metrics{grid-template-columns:repeat(2,1fr)}.identity{gap:17px}.identity .range{flex-direction:column}.readiness{grid-template-columns:1fr}.readiness div:nth-child(2){align-items:flex-start;flex-direction:column;gap:2px}}
</style>
